csrf_token();
$schemaReady=adena_module_table_exists('expense_categories') && adena_module_table_exists('expenses') && adena_module_table_exists('payment_requests');
$tab=(string)($_GET['tab']??'summary');
if(!in_array($tab,['summary','expenses','payments','settings','purchases'],true)) $tab='summary';
$month=$_GET['month']??date('Y-m'); if(!preg_match('/^\d{4}-\d{2}$/',$month)) $month=date('Y-m');
[$month,$start,$end]=adena_period_bounds($month);
$err=''; $ok=''; $uid=(int)($me['id']??0);

function adena_finance_category(int $id): ?array {
  if($id<=0) return null;
  $st=db()->prepare('SELECT * FROM expense_categories WHERE id=? AND deleted_at IS NULL LIMIT 1'); $st->execute([$id]);
  return $st->fetch(PDO::FETCH_ASSOC) ?: null;
}
function adena_finance_status_label(string $s): string { return match($s){'draft'=>'Draft','submitted'=>'Diajukan','approved'=>'Disetujui','paid'=>'Dibayar','rejected'=>'Ditolak','cancelled'=>'Dibatalkan',default=>$s}; }

if($schemaReady && $_SERVER['REQUEST_METHOD']==='POST'){
  try{
    csrf_check(); $action=(string)($_POST['action']??'');
    if($action==='save_category'){
      $id=(int)($_POST['id']??0); $code=strtoupper(trim((string)($_POST['category_code']??''))); $name=trim((string)($_POST['category_name']??''));
      if($code==='') $code='CUSTOM-'.date('YmdHis'); if($name==='') throw new Exception('Nama kategori wajib diisi.');
      $data=[$code,$name,trim((string)($_POST['group_name']??'')),trim((string)($_POST['description']??'')),isset($_POST['requires_approval'])?1:0,isset($_POST['requires_evidence'])?1:0,(int)($_POST['sort_order']??0)];
      if($id>0){$data[]=$id;db()->prepare('UPDATE expense_categories SET category_code=?,category_name=?,group_name=?,description=?,requires_approval=?,requires_evidence=?,sort_order=?,updated_at=NOW() WHERE id=?')->execute($data);}else{$data=array_merge([adena_uuid_v4()],$data,[$uid]);db()->prepare('INSERT INTO expense_categories(record_uuid,category_code,category_name,group_name,description,requires_approval,requires_evidence,sort_order,is_active,created_by) VALUES(?,?,?,?,?,?,?,?,1,?)')->execute($data);}
      $ok='Jenis pengeluaran disimpan.'; $tab='settings';
    } elseif($action==='toggle_category'){
      $id=(int)($_POST['id']??0);$active=(int)($_POST['active']??0)===1?1:0;db()->prepare('UPDATE expense_categories SET is_active=?,updated_at=NOW() WHERE id=?')->execute([$active,$id]);$ok='Status kategori diperbarui.';$tab='settings';
    } elseif($action==='save_expense'){
      $category=adena_finance_category((int)($_POST['category_id']??0)); if(!$category) throw new Exception('Jenis pengeluaran wajib dipilih.');
      $amount=(float)($_POST['amount']??0);$title=trim((string)($_POST['title']??''));$status=(string)($_POST['status']??'paid');if(!in_array($status,['draft','submitted','approved','paid'],true))$status='paid';
      if($title==='') throw new Exception('Uraian singkat wajib diisi.'); if($amount<=0) throw new Exception('Nominal harus lebih dari nol.'); if($category['category_code']==='OTHER' && trim((string)($_POST['description']??''))==='') throw new Exception('Kategori Lain-lain memerlukan uraian rinci.');
      $no='EXP-'.date('Ymd-His').'-'.str_pad((string)random_int(1,999),3,'0',STR_PAD_LEFT);$now=date('Y-m-d H:i:s');
      db()->prepare('INSERT INTO expenses(record_uuid,expense_no,expense_date,category_id,category_name_snapshot,title,description,amount,vendor_name,payment_method,reference_no,evidence_reference,status,due_date,approved_by,approved_at,paid_by,paid_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([
        adena_uuid_v4(),$no,(string)($_POST['expense_date']??date('Y-m-d')),(int)$category['id'],$category['category_name'],$title,trim((string)($_POST['description']??'')),$amount,trim((string)($_POST['vendor_name']??'')),trim((string)($_POST['payment_method']??'')),trim((string)($_POST['reference_no']??'')),trim((string)($_POST['evidence_reference']??'')),$status,($_POST['due_date']??'')?:null,in_array($status,['approved','paid'],true)?$uid:null,in_array($status,['approved','paid'],true)?$now:null,$status==='paid'?$uid:null,$status==='paid'?$now:null,$uid
      ]);$id=(int)db()->lastInsertId();adena_finance_audit('expense',$id,'created',['status'=>$status,'amount'=>$amount],$uid);adena_finance_outbox('expense',(string)$id,'created',['expense_no'=>$no,'status'=>$status,'amount'=>$amount]);$ok='Pengeluaran berhasil dicatat.';$tab='expenses';
    } elseif($action==='save_payment_request'){
      $category=adena_finance_category((int)($_POST['category_id']??0)); if(!$category) throw new Exception('Jenis pengeluaran wajib dipilih.');$amount=(float)($_POST['amount']??0);$title=trim((string)($_POST['title']??''));if($title===''||$amount<=0) throw new Exception('Judul dan nominal permintaan wajib diisi.');if($category['category_code']==='OTHER' && trim((string)($_POST['description']??''))==='') throw new Exception('Kategori Lain-lain memerlukan uraian rinci.');
      $no='PAYREQ-'.date('Ymd-His').'-'.str_pad((string)random_int(1,999),3,'0',STR_PAD_LEFT);
      db()->prepare('INSERT INTO payment_requests(record_uuid,request_no,request_date,category_id,category_name_snapshot,title,description,amount,vendor_name,due_date,reference_no,evidence_reference,status,requested_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,\'submitted\',?)')->execute([adena_uuid_v4(),$no,(string)($_POST['request_date']??date('Y-m-d')),(int)$category['id'],$category['category_name'],$title,trim((string)($_POST['description']??'')),$amount,trim((string)($_POST['vendor_name']??'')),($_POST['due_date']??'')?:null,trim((string)($_POST['reference_no']??'')),trim((string)($_POST['evidence_reference']??'')),$uid]);$id=(int)db()->lastInsertId();adena_finance_audit('payment_request',$id,'submitted',['amount'=>$amount],$uid);adena_finance_outbox('payment_request',(string)$id,'created',['request_no'=>$no,'status'=>'submitted','amount'=>$amount]);$ok='Permintaan pembayaran diajukan.';$tab='payments';
    } elseif($action==='payment_action'){
      $id=(int)($_POST['id']??0);$new=(string)($_POST['new_status']??'');if(!in_array($new,['approved','paid','rejected','cancelled'],true)) throw new Exception('Status tidak valid.');$st=db()->prepare('SELECT * FROM payment_requests WHERE id=? LIMIT 1 FOR UPDATE');db()->beginTransaction();$st->execute([$id]);$r=$st->fetch(PDO::FETCH_ASSOC);if(!$r)throw new Exception('Permintaan tidak ditemukan.');
      $linked=(int)($r['linked_expense_id']??0);$now=date('Y-m-d H:i:s');
      if($new==='paid' && $linked<=0){db()->prepare('INSERT INTO expenses(record_uuid,expense_no,expense_date,category_id,category_name_snapshot,title,description,amount,vendor_name,reference_no,evidence_reference,status,approved_by,approved_at,paid_by,paid_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([adena_uuid_v4(),'EXP-'.date('Ymd-His').'-'.str_pad((string)random_int(1,999),3,'0',STR_PAD_LEFT),date('Y-m-d'),$r['category_id'],$r['category_name_snapshot'],$r['title'],$r['description'],$r['amount'],$r['vendor_name'],$r['reference_no'],$r['evidence_reference'],'paid',$uid,$now,$uid,$now,$uid]);$linked=(int)db()->lastInsertId();}
      db()->prepare('UPDATE payment_requests SET status=?,approved_by=IF(? IN (\'approved\',\'paid\'),?,approved_by),approved_at=IF(? IN (\'approved\',\'paid\'),?,approved_at),paid_by=IF(?=\'paid\',?,paid_by),paid_at=IF(?=\'paid\',?,paid_at),linked_expense_id=IF(? > 0,?,linked_expense_id),rejection_reason=?,version_no=version_no+1,updated_at=NOW() WHERE id=?')->execute([$new,$new,$uid,$new,$now,$new,$uid,$new,$now,$linked,$linked,trim((string)($_POST['reason']??'')),$id]);
      adena_finance_audit('payment_request',$id,'status_'.$new,['old_status'=>$r['status'],'new_status'=>$new,'linked_expense_id'=>$linked],$uid);adena_finance_outbox('payment_request',(string)$id,'updated',['status'=>$new,'linked_expense_id'=>$linked],(int)$r['version_no']+1);$db=db();$db->commit();$ok='Status permintaan diperbarui menjadi '.adena_finance_status_label($new).'.';$tab='payments';
    }
  }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}
}

$categories=$schemaReady?(db()->query('SELECT * FROM expense_categories WHERE deleted_at IS NULL ORDER BY is_active DESC,sort_order,category_name')->fetchAll(PDO::FETCH_ASSOC)?:[]):[];
$activeCategories=array_values(array_filter($categories,static fn($r)=>(int)$r['is_active']===1));
$expenses=[];$payments=[];$purchases=[];$summary=['purchases'=>0,'expenses'=>0,'pending'=>0,'paid_requests'=>0];
if($schemaReady){
  $st=db()->prepare('SELECT e.*,c.category_code,u.name created_by_name FROM expenses e LEFT JOIN expense_categories c ON c.id=e.category_id LEFT JOIN users u ON u.id=e.created_by WHERE e.expense_date>=? AND e.expense_date<? AND e.deleted_at IS NULL ORDER BY e.id DESC');$st->execute([$start,$end]);$expenses=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
  $st=db()->prepare('SELECT p.*,u.name requested_by_name FROM payment_requests p LEFT JOIN users u ON u.id=p.requested_by WHERE p.request_date>=? AND p.request_date<? AND p.deleted_at IS NULL ORDER BY p.id DESC');$st->execute([$start,$end]);$payments=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
  foreach($expenses as $r){if(in_array($r['status'],['approved','paid'],true))$summary['expenses']+=(float)$r['amount'];}
  foreach($payments as $r){if(in_array($r['status'],['draft','submitted','approved'],true))$summary['pending']+=(float)$r['amount'];if($r['status']==='paid')$summary['paid_requests']+=(float)$r['amount'];}
}
try{$st=db()->prepare("SELECT ph.*,s.supplier_name FROM purchase_headers ph LEFT JOIN suppliers s ON s.id=ph.supplier_id WHERE ph.purchase_date>=? AND ph.purchase_date<? AND ph.status<>'cancelled' ORDER BY ph.id DESC");$st->execute([$start,$end]);$purchases=$st->fetchAll(PDO::FETCH_ASSOC)?:[];foreach($purchases as $r)if(($r['status']??'')==='posted')$summary['purchases']+=(float)$r['grand_total'];}catch(Throwable $e){}
$customCss=setting('custom_css','');
?>
