$r['amount'],0,',','.'); ?></td><td><?php echo e(adena_finance_status_label($r['status'])); ?></td></tr><?php endforeach;if(!$expenses): ?><tr><td colspan="5">Belum ada pengeluaran.</td></tr><?php endif; ?></tbody></table></div>
