ction" value="payment_action"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><button class="btn btn-light" name="new_status" value="approved">Setujui</button> <button class="btn" name="new_status" value="paid">Tandai Dibayar</button> <button class="btn btn-danger" name="new_status" value="rejected">Tolak</button></form><?php else: ?>-<?php endif; ?></td></tr><?php endforeach;if(!$payments): ?><tr><td colspan="6">Belum ada permintaan pembayaran.</td></tr><?php endif; ?></tbody></table></div>
